import React, { useState } from 'react';
import BuyerForm from '../BuyerForm';
import SupplierForm from './SupplierForm';

const AddOfferPage = ({ user, onNavigate }) => {
    const [type, setType] = useState('buyer');

    return (
        <div className="container mx-auto px-4 py-8">
            <h1 className="text-3xl font-bold mb-6 text-center">Add Sourcing Offer</h1>
            <div className="mb-6 flex justify-center space-x-4">
                <button
                    onClick={() => setType('buyer')}
                    className={`px-4 py-2 rounded ${type === 'buyer' ? 'bg-teal-700 text-white' : 'bg-gray-200'}`}
                >
                    I'm a Buyer
                </button>
                <button
                    onClick={() => setType('supplier')}
                    className={`px-4 py-2 rounded ${type === 'supplier' ? 'bg-teal-700 text-white' : 'bg-gray-200'}`}
                >
                    I'm a Supplier
                </button>
            </div>
            {type === 'buyer' ? (
                <BuyerForm user={user} onNavigate={onNavigate} />
            ) : (
                <SupplierForm user={user} onNavigate={onNavigate} />
            )}
        </div>
    );
};

export default AddOfferPage;
